dtsPropsFor.ActivityFeed:
/**
   * Feed rows, newest first. Item shape:
   *   {
   *     id: string;                 // stable key
   *     title: React.ReactNode;     // bold lead line, e.g. "Stamp issued"
   *     description?: React.ReactNode;
   *     timestamp?: string;         // ISO string; right-aligned, formatted en-GB
   *     metadata?: React.ReactNode; // small muted line under the description
   *     tone?: "accent" | "ink" | "leaf" | "sun" | "plain"; // leading dot colour
   *   }
   */
  items: ActivityFeedItem[];
  /** Rendered in place of the list when `items` is empty (e.g. an <EmptyState>). */
  emptyState?: React.ReactNode;
  className?: string;

dtsPropsFor.DataTable:
/** Accessible table caption (visually hidden via <caption class="sr-only">). */
  caption: string;
  /**
   * Column definitions. Column shape (DataTableColumn<T>):
   *   {
   *     key: string;                      // React key + cell key
   *     header: React.ReactNode;          // rendered inside an uppercase Eyebrow
   *     cell: (row: T) => React.ReactNode; // per-row cell renderer
   *     className?: string;               // applied to <th> and <td>
   *   }
   */
  columns: DataTableColumn<T>[];
  /** Row data; `T` is your row type. */
  rows: T[];
  /** Stable key per row. */
  getRowKey: (row: T, index: number) => string;
  /** Rendered instead of the table body when `rows` is empty. */
  emptyState?: React.ReactNode;
  className?: string;
  rowClassName?: (row: T, index: number) => string | undefined;
  onRowClick?: (row: T, index: number) => void;
  /**
   * Opt-in mobile renderer. When set, phone widths (below `cardBreakpoint`)
   * show this card per row instead of a horizontally scrolling table.
   */
  mobileCard?: (row: T, index: number) => React.ReactNode;
  /** Class on the mobile-card list (only when `mobileCard` is set). */
  mobileClassName?: string;
  /**
   * Breakpoint at which the card stack switches to the semantic table
   * (only when `mobileCard` is set). Default "sm".
   */
  cardBreakpoint?: "sm" | "lg" | "xl";

dtsPropsFor.FunnelChart:
